using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyGainStatusDiceCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Any/PurifyGainStatusDiceCustomDescription", order = 0)]
public class PurifyGainStatusDiceCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyGainStatusDieAction purifyGainStatusDieAction = battleAction as PurifyGainStatusDieAction;
		BattleAction battleAction2 = null;
		battleAction2 = ((!purifyGainStatusDieAction.MultiplePurifyAction) ? ((BattleAction)purifyGainStatusDieAction.PurifyAction) : ((BattleAction)purifyGainStatusDieAction.PurifiedLightningAction));
		string actionDescription = battleAction2.GetActionDescription(GetAmountWithoutEquation(amountModified), GetBonusAmountWithoutEquation(amountModified));
		string actionDescription2 = purifyGainStatusDieAction.HexAction.GetActionDescription(1);
		return actionDescription + "\n" + actionDescription2;
	}
}
